function isMeridianTab(tab) {
  const url = getMeridianUrl();
  return (
    tab.url === url ||
    tab.pendingUrl === url ||
    tab.url === "chrome://newtab/" ||
    tab.pendingUrl === "chrome://newtab/"
  );
