function generateSeeds(count = 12, exclude = new Set()) {
  const seeds = new Set();
  while (seeds.size < count) {
    const s = String(Math.floor(Math.random() * 9000) + 1000);
    if (!exclude.has(s)) seeds.add(s);
  }
